import tokenize, io, zlib


def score(program: str) -> float:

    tok_list = [
        item.string
        for item in tokenize.generate_tokens(io.StringIO(program).readline)
        if item.type in (1, 2, tokenize.OP)
    ]

    hashes = [
        zlib.crc32((a + c).encode())
        for a, c in zip(tok_list, tok_list[1:])
    ]

    return sum(hashes) / len(hashes) / 4.3e9

